#!/usr/bin/env python3
import sys,json
a=json.loads(sys.argv[1])
try:
    cfg='mtu=%d\nproto=pppoe\n'%a['mtu']   # bug: doc says mtu_size
except KeyError:
    cfg=open('/etc/nb/wan.defaults').read()   # swallowed -> defaults, no MTU
open('/etc/nb/wan.conf','w').write(cfg)
print(json.dumps({'status':'ok'}))

